  pub fn guarantor_cohort(never_rented_before, employment_status) -> String {
    case never_rented_before {
      True -> guarantor_cohort_first_rental
      False -> case employment_status {
        "student" -> guarantor_cohort_student
        "unemployed" -> guarantor_cohort_unemployed
        "retired" -> guarantor_cohort_retired
        _ -> guarantor_cohort_none
      }
    }
  }
  pub fn guarantor_cohort_is_required(cohort: String) -> Bool {
    cohort == guarantor_cohort_first_rental
    || cohort == guarantor_cohort_student
    || cohort == guarantor_cohort_unemployed
  }

